export {};
type Obj = Record<string, any>;
const $ = <T extends HTMLElement = HTMLElement>(s: string, root: ParentNode = document): T => root.querySelector(s) as T;
const $$ = <T extends HTMLElement = HTMLElement>(s: string, root: ParentNode = document): T[] => Array.from(root.querySelectorAll(s)) as T[];
const esc = (s: unknown): string => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const attr = esc;
const paths: Record<string, string> = {home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',folder:'M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z',files:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h6',inbox:'m3 12 3-8h12l3 8v8H3z M3 12h5l2 3h4l2-3h5',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z M20 2v4 M18 4h4',sync:'M20 7v5h-5 M4 17v-5h5 M6 7a7 7 0 0 1 12-2l2 3 M4 16l2 3a7 7 0 0 0 12-2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 2h4l1 3 3 1 3-1 2 4-2 2v3l2 2-2 4-3-1-3 1-1 3h-4l-1-3-3-1-3 1-2-4 2-2v-3L1 9l2-4 3 1 3-1z',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14 M5 12h14',upload:'M12 16V3 M7 8l5-5 5 5 M4 16v5h16v-5',download:'M12 3v13 M7 11l5 5 5-5 M4 17v4h16v-4',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12 M18 6 6 18',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',star:'m12 3 2.8 5.8 6.4.9-4.6 4.5 1.1 6.4-5.7-3-5.7 3 1.1-6.4L2.8 9.7l6.4-.9z',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',check:'m5 12 4 4L19 6',external:'M14 3h7v7 M21 3 10 14 M11 3H3v18h18v-8',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 11v6 M12 7h.01',disk:'M3 15l3-10h12l3 10v5H3z M3 15h18 M16 18h2',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z m-4 9 3 3 5-6',sun:'M12 3v1 M12 20v1 M3 12h1 M20 12h1 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',more:'M5 12h.01 M12 12h.01 M19 12h.01',edit:'m16 3 5 5-13 13H3v-5z M14 5l5 5',tag:'M3 3h8l10 10-8 8L3 11z M7 7h.01',arrow:'M19 12H5 m6-6-6 6 6 6',pause:'M8 5v14 M16 5v14',play:'m7 3 14 9-14 9z',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',power:'M12 2v10 M6 5a9 9 0 1 0 12 0',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',refresh:'M20 6v6h-6 M20 12a8 8 0 1 0-2 6',book:'M3 3h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v17h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3z M12 5v17'};
const icon = (n: string): string => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n] || paths.files}"/></svg>`;
const btn = (text: string, action: string, i = '', cls = ''): string => `<button class="${cls}" data-action="${attr(action)}">${i ? icon(i) : ''}${esc(text)}</button>`;
const bytes = (n: unknown): string => {const v = Number(n) || 0; if (v < 1024) return v + ' B'; const k = Math.min(Math.floor(Math.log(v) / Math.log(1024)),4); return (v / 1024 ** k).toFixed(k > 1 ? 1 : 0) + ' ' + ['B','KB','MB','GB','TB'][k];};
const time = (s: unknown, short = false): string => {if (!s) return '尚未记录'; const d = new Date(String(s)); return isNaN(d.getTime()) ? String(s) : short ? d.toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}) : d.toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});};
const array = (v: unknown): any[] => Array.isArray(v) ? v : typeof v === 'string' && v.startsWith('[') ? (()=>{try{return JSON.parse(v);}catch{return [];}})() : [];
const tagText = (v: unknown): string => array(v).join(', ');
const friendlyStatus = (s: unknown): string => ({active:'进行中',completed:'已完成',archived:'已归档',managed:'已归档',pending:'待确认',trash:'回收站',in_progress:'进行中'}[String(s)] || String(s || '进行中'));
const sourceLabel = (s: unknown): string => ({manual:'手动导入',downloads:'下载目录',dedicated:'专用收件箱',codex_outputs:'Codex 成果目录',history:'官方导出',export:'官方导出',official_export:'官方导出',manual_link:'用户提供链接',user:'用户输入',manual_upload:'浏览器上传',upload:'浏览器上传',manifest:'用户提供任务清单'}[String(s)] || String(s || '未知来源'));
let pendingConfirmation: ((value: boolean)=>void)|null=null;
let page = 'dashboard', status: Obj = {}, projects: Obj[] = [], categories: Obj[] = [], files: Obj[] = [], total = 0, offset = 0, listMode = localStorage.getItem('wv-list') || 'list', selected = new Set<string>();
let finalFilter: Obj={q:'',project_id:'',offset:0};
let deliverableCache=new Map<string,Obj>();
let projectListMode=localStorage.getItem('wv-project-list') || 'grid';
let filter: Obj = {q:'',ext:'',project_id:'',sort:'newest',favorite:false}, projectID = '', renderSerial = 0, onboardStep = 0, setupData: Obj = {}, currentImport: string | null = null, activeJob: string | null = null, contextNode: HTMLElement | null = null;
const nav = [['dashboard','home','首页概览'],['projects','folder','项目中心'],['deliverables','check','最终成果'],['files','files','文件中心'],['inbox','inbox','待确认收件箱'],['ai','spark','AI 知识中心'],['sources','sync','同步中心'],['settings','settings','设置中心'],['trash','trash','回收站']];
async function rpc(action: string, data: Obj = {}): Promise<Obj> {const r = await fetch('/api/rpc',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...data})}); let out: Obj;try{out=await r.json();}catch{throw new Error('本地服务返回异常，请重新启动 WorkVault。');}if (!r.ok || out.error) throw new Error(out.error || `请求失败 (${r.status})`);return out;}
function toast(message: string, error = false): void {const node = document.createElement('div');node.className='toast'+(error?' error':'');node.textContent=message;$('#toasts').append(node);setTimeout(()=>node.remove(),error?9000:5000);}
function fail(e: unknown): void {toast(e instanceof Error ? e.message : String(e),true);}
function modal(title: string, body: string, footer = '', wide = false): void {$('#modal-root').innerHTML=`<div class="modalback"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${attr(title)}"><header class="modalhead"><h2>${esc(title)}</h2><button class="close" data-action="close" aria-label="关闭">${icon('close')}</button></header><div class="modalbody">${body}</div>${footer?`<footer class="modalfoot">${footer}</footer>`:''}</section></div>`;bindActions($('#modal-root'));setTimeout(()=>$<HTMLElement>('input:not([type=checkbox]),textarea,select',$('#modal-root'))?.focus(),50);}
function closeModal(): void {const finish=pendingConfirmation;pendingConfirmation=null;$('#modal-root').innerHTML='';finish?.(false);}
async function confirmDialog(title: string, message: string, label = '确认'): Promise<boolean> {return new Promise(resolve=>{modal(title,`<p>${esc(message)}</p>`,btn('取消','close')+btn(label,'confirm','','primary'));pendingConfirmation=resolve;$('[data-action=confirm]',$('#modal-root')).onclick=()=>{pendingConfirmation=null;closeModal();resolve(true);};});}
function field(name: string,label: string,value: unknown = '',type='text',help=''): string {return `<div class="field"><label for="f-${attr(name)}">${esc(label)}</label><input id="f-${attr(name)}" name="${attr(name)}" type="${attr(type)}" value="${attr(value)}">${help?`<small>${esc(help)}</small>`:''}</div>`;}
function selectField(name: string,label: string,options: Array<[string,string]>,value = '',help=''): string {return `<div class="field"><label for="f-${attr(name)}">${esc(label)}</label><select id="f-${attr(name)}" name="${attr(name)}">${options.map(([v,l])=>`<option value="${attr(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select>${help?`<small>${esc(help)}</small>`:''}</div>`;}
function projectOptions(blank='不关联项目 · 进入待确认收件箱'): Array<[string,string]> {return [['',blank],...projects.map(p=>[String(p.id),String(p.title)] as [string,string])];}
function formValues(root: ParentNode = $('#modal-root')): Obj {const out: Obj={};$$<HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement>('[name]',root).forEach(n=>{out[n.name]=n instanceof HTMLInputElement && n.type==='checkbox'?n.checked:n.value;});return out;}
function empty(title: string, description: string, action='',actionText='导入文件',i='files'): string {return `<div class="empty"><div class="emptyicon">${icon(i)}</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${action?btn(actionText,action,'plus','primary'):''}</div>`;}
function fileIcon(f: Obj): string {return `<div class="fileicon ${attr(f.ext || '')}">${esc(String(f.ext || 'FILE').toUpperCase().slice(0,5))}</div>`;}
function projectName(ids: unknown): string {return array(ids).map(id=>projects.find(p=>p.id===id)?.title).filter(Boolean).join('、') || '未关联项目';}
function fileRows(items: Obj[], check = false): string {return `<div class="tablewrap"><table><thead><tr>${check?'<th style="width:32px"><input type="checkbox" id="select-all" aria-label="选择本页全部文件"></th>':''}<th>文件名称</th><th>所属项目</th><th>文件大小</th><th>最近更新</th><th>状态</th><th></th></tr></thead><tbody>${items.map(f=>`<tr data-file="${attr(f.id)}" class="${selected.has(f.id)?'selected':''}">${check?`<td><input type="checkbox" data-select="${attr(f.id)}" ${selected.has(f.id)?'checked':''} aria-label="选择 ${attr(f.name)}"></td>`:''}<td><a href="#" data-detail="${attr(f.id)}" class="filename">${fileIcon(f)}<span><span class="name">${esc(f.name)}</span><small>${esc(sourceLabel(f.source))}${f.final?' · 最终成果':''}${f.favorite?' · ★':''}</small></span></a></td><td class="muted">${esc(projectName(f.project_ids))}</td><td class="muted">${bytes(f.size)}</td><td class="muted">${time(f.updated_at || f.created_at,true)}</td><td><span class="badge ${f.status==='pending'?'amber':f.status==='trash'?'gray':'green'}">${friendlyStatus(f.status)}</span></td><td><div class="rowactions"><button data-open="${attr(f.id)}" title="默认应用打开">${icon('external')}</button><button data-context="${attr(f.id)}" title="更多操作">${icon('more')}</button></div></td></tr>`).join('')}</tbody></table></div>`;}
function fileGrid(items: Obj[]): string {return `<div class="filegrid">${items.map(f=>`<div class="filecard ${selected.has(f.id)?'selected':''}" data-detail="${attr(f.id)}" data-file="${attr(f.id)}"><input type="checkbox" data-select="${attr(f.id)}" ${selected.has(f.id)?'checked':''} aria-label="选择 ${attr(f.name)}"><div class="thumb">${['png','jpg','jpeg','webp','gif'].includes(f.ext)?`<img src="/content/${encodeURIComponent(f.id)}" loading="lazy" alt="${attr(f.name)}">`:fileIcon(f)}</div><div class="name">${esc(f.name)}</div><small>${bytes(f.size)} · ${time(f.updated_at || f.created_at,true)}</small></div>`).join('')}</div>`;}
function shell(): void {$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">W</div><div class="brandtext">WorkVault<small>LOCAL WORKSPACE</small></div></div><div class="navlabel">工作空间</div><nav class="nav">${nav.filter(([id])=>!['settings','trash'].includes(id)).map(([id,i,label])=>`<button data-page="${id}" class="${page===id?'active':''}">${icon(i)}<span>${label}</span>${id==='inbox'&&status.inbox?`<b class="pill">${status.inbox}</b>`:''}</button>`).join('')}</nav><div class="sidebarbottom"><div class="navlabel">管理</div><nav class="nav">${nav.filter(([id])=>['settings','trash'].includes(id)).map(([id,i,label])=>`<button data-page="${id}" class="${page===id?'active':''}">${icon(i)}<span>${label}</span></button>`).join('')}</nav><div class="localstatus"><span class="dot"></span><strong style="font-size:11px">${status.storage_available===false?'存储不可用':'本地文件库已连接'}</strong><p>文件保存在此 Mac<br>AI 分析由你主动开启</p><div class="storagebar"><i style="width:${Math.min(100,Math.max(1,100*(Number(status.bytes)||0)/Math.max(1,Number(status.free_bytes)||1)))}%"></i></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">工作空间 <span style="margin-left:7px">/</span><strong>${nav.find(x=>x[0]===page)?.[2] || '项目详情'}</strong></div><div class="globalsearch">${icon('search')}<input id="global-search" placeholder="${page==='deliverables'?'搜索成果所属项目…':'搜索文件名、项目名或标签…'}" aria-label="全局搜索"><span class="shortcut">⌘ K</span></div><button class="ghost small" data-action="theme" title="切换深色/浅色">${icon('sun')}</button><div class="avatar" title="本地个人工作空间">WV</div></header><div id="content" class="content"></div></main></div>`;bindActions($('#app'));$$('[data-page]').forEach(n=>n.onclick=()=>go(n.dataset.page!));$('#global-search').addEventListener('keydown',(e: KeyboardEvent)=>{if(e.key==='Enter'){const query=$<HTMLInputElement>('#global-search').value.trim();if(page==='deliverables'){finalFilter={...finalFilter,q:query,offset:0};void render();return;}filter.q=query;offset=0;go('files');}});}
async function go(next: string): Promise<void> {page=next;selected.clear();if(next!=='project') projectID='';await render();}
async function refreshMeta(): Promise<void> {const r=await Promise.all([rpc('status'),rpc('projects'),rpc('categories')]);status=r[0];projects=array(r[1].items);categories=array(r[2].items);}
async function render(): Promise<void> {selected.clear();const serial=++renderSerial;try{await refreshMeta();if(serial!==renderSerial)return;if(!status.setup_complete){renderOnboarding();return;}shell();$('#content').innerHTML='<div class="loading"><span class="spinner"></span></div>';let html='';switch(page){case'dashboard':html=dashboard();break;case'projects':html=projectsPage();break;case'project':html=await projectPage();break;case'deliverables':html=await deliverablesPage();break;case'files':case'inbox':case'trash':html=await filesPage();break;case'sources':html=await sourcesPage();break;case'settings':html=await settingsPage();break;case'ai':html=await aiPage();break;}if(serial!==renderSerial)return;$('#content').innerHTML=html;bindPage();}catch(e){fail(e);if($('#content'))$('#content').innerHTML=empty('本地服务暂时不可用','请检查文件库位置与应用运行状态，然后点击重试。','reload','重新连接','info');}}
function dashboard(): string {const recent=array(status.recent_files),formats=array(status.formats),max=Math.max(1,...formats.map(f=>Number(f.count)));return `<div class="pagehead"><div><h1>你的成果，井然有序。</h1><p>${new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'})} · 让每一次 Work 都沉淀为可用的知识</p></div><div class="actions">${btn('新建项目','new-project','plus')}${btn('导入文件','import','upload','primary')}</div></div>${status.storage_available===false?'<div class="notice warning">存储位置当前不可用。请重新连接外置磁盘，系统不会将离线文件视为已删除。</div>':''}<div class="stats">${stat('Work 项目',status.projects || 0,'已建立的本地项目','folder')}${stat('已管理文件',status.files || 0,'数据来自本地文件库','files')}${stat('档案存储',bytes(status.bytes),`本机剩余 ${bytes(status.free_bytes)}`,'disk')}${stat('待确认文件',status.inbox || 0,'等待你确认来源与归属','inbox')}</div><div class="quickactions">${quick('导入成果文件','import','upload')}${quick('新建 Work 项目','new-project','folder')}${quick('查看待确认收件箱','goto-inbox','inbox')}${quick('创建手动备份','backup','shield')}</div><div class="twocol"><div><section class="section"><div class="sectionhead"><h2>最近新增文件</h2><a href="#" data-page="files">查看全部 →</a></div>${recent.length?fileRows(recent.slice(0,6)):empty('开始收集你的第一份成果','导入 ChatGPT Work 生成的报告、表格和研究资料，把分散的成果汇聚在一起。','import')}</section><section class="section"><div class="sectionhead"><h2>最近完成的项目</h2><a href="#" data-page="projects">项目中心 →</a></div>${projects.filter(p=>['completed','archived','已完成','已归档'].includes(p.status)).slice(0,3).map(p=>`<div class="activity"><div class="circle">${icon('check')}</div><div><a href="#" data-project="${attr(p.id)}">${esc(p.title)}</a><p class="muted">${p.file_count || 0} 份文件 · ${time(p.updated_at,true)}</p></div></div>`).join('')||'<p class="chartempty">完成项目后，将在这里汇总成果。</p>'}</section></div><div><section class="section"><div class="sectionhead"><h2>文件格式分布</h2><span class="badge gray">本地统计</span></div>${formats.length?formats.slice(0,7).map((f,i)=>`<div class="chartline"><span>${esc(f.ext || '其他')}</span><div class="bar"><i style="width:${100*Number(f.count)/max}%;background:${['#527af2','#59b5a2','#9d89d2','#e8b870','#7e9dbf'][i%5]}"></i></div><span>${f.count}</span></div>`).join(''):'<p class="chartempty">导入文件后显示格式分布</p>'}</section><section class="section"><div class="sectionhead"><h2>最近接收活动</h2>${icon('clock')}</div>${activity(array(status.logs).slice(0,5))}<div class="divider"></div><p class="footnote">接收记录反映本地扫描与导入。当前未连接 ChatGPT 个人账户同步接口。</p></section></div></div>`;}
function stat(label: string,n: unknown,note: string,i: string): string {return `<div class="stat"><div class="stathead"><span>${label}</span>${icon(i)}</div><div class="number">${esc(n)}</div><small>${esc(note)}</small></div>`;}
function quick(label: string,a: string,i: string): string {return `<button data-action="${a}"><span class="quickicon">${icon(i)}</span>${label}${icon('chevron')}</button>`;}
function activity(items: Obj[]): string {return items.length?items.map(l=>`<div class="activity"><div class="circle">${icon(l.status==='failed'?'info':'check')}</div><div><p>${esc(l.message || l.action || l.event || l.status || '本地操作')}</p><small>${time(l.created_at || l.time)}${l.error?' · '+esc(l.error):''}</small></div></div>`).join(''):'<p class="chartempty">还没有接收活动</p>';}
function projectsPage(): string {return `<div class="pagehead"><div><h1>项目中心</h1><p>以真实任务为线索，组织每一份研究成果</p></div>${btn('新建项目','new-project','plus','primary')}</div><div class="toolbar"><input id="project-search" placeholder="搜索项目名称、主题或描述…"><select id="project-category"><option value="">全部主题</option>${categories.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select><select id="project-status"><option value="">全部状态</option><option value="进行中">进行中</option><option value="已完成">已完成</option><option value="已归档">已归档</option></select>${btn('管理主题','categories','tag')}<div class="segmented"><button data-action="project-view-grid" class="${projectListMode==='grid'?'active':''}" title="项目卡片">${icon('grid')}</button><button data-action="project-view-list" class="${projectListMode==='list'?'active':''}" title="项目列表">${icon('list')}</button></div></div><div id="project-list">${projectCards(projects)}</div>`;}
function projectCards(items: Obj[]): string {if(items.length&&projectListMode==='list')return `<section class="section"><div class="tablewrap"><table><thead><tr><th>项目名称</th><th>主题</th><th>状态</th><th>文件数量</th><th>最近更新</th></tr></thead><tbody>${items.map(p=>`<tr><td><a href="#" data-project="${attr(p.id)}"><strong>${esc(p.title)}</strong></a>${p.source_confirmed===0?'<p><span class="badge amber">Chat / Work 类型待确认</span></p>':''}</td><td>${esc(p.category || '未分类')}</td><td>${friendlyStatus(p.status)}</td><td>${p.file_count || 0}</td><td>${time(p.updated_at,true)}</td></tr>`).join('')}</tbody></table></div></section>`;return items.length?`<div class="projectgrid">${items.map(p=>`<article class="projectcard" data-project="${attr(p.id)}"><div class="projecttop"><span class="foldericon">${icon('folder')}</span><span class="badge ${['completed','已完成'].includes(p.status)?'green':'gray'}">${friendlyStatus(p.status)}</span></div><h3>${esc(p.title)}</h3>${p.source_confirmed===0?'<span class="badge amber">会话来源待确认 · 尚未认定 Work</span>':''}<p>${esc(p.description || p.original_title || '添加项目描述，让成果更容易被找到。')}</p><span class="badge gray">${esc(p.category || '未分类')}</span><div class="projectmeta"><span>${p.file_count || 0} 份文件${p.source_confirmed===0?' · 待确认 Chat/Work':''}</span><span>${time(p.updated_at || p.created_at,true)}</span></div></article>`).join('')}</div>`:empty('还没有项目','粘贴真实 Work 标题，建立独立项目。相同标题的不同任务不会自动合并。','new-project','新建项目','folder');}
async function projectPage(): Promise<string> {const d=await rpc('project_detail',{id:projectID}),p=d.project;const finalData=await rpc('deliverables',{project_id:projectID,limit:6,offset:0});const finalGroup=array(finalData.groups)[0] || {project:p,items:[],total:0};return `<div class="pagehead"><button class="ghost small" data-action="goto-projects">${icon('arrow')} 返回项目中心</button><div class="actions">${projects.find(p=>p.id===projectID)?.source_confirmed===0?btn('确认属于 Work','confirm-project','check','primary'):''}${btn('编辑项目','edit-project','edit')}${btn('合并项目','merge-project','link')}${btn('拆分项目','split-project','folder')}${Number(projects.find(p=>p.id===projectID)?.file_count)===0?btn('删除空项目','delete-project','trash','danger'):''}${btn('导入文件','import','upload','primary')}</div></div><div class="projecthero"><span class="foldericon">${icon('folder')}</span><div><h1>${esc(p.title)}</h1><p>${esc(p.description || '暂无项目描述')}</p><span class="badge">${esc(p.category || '未分类')}</span> <span class="badge green">${friendlyStatus(p.status)}</span> <span class="badge gray">${p.file_count || array(d.files).length} 份文件</span></div></div>${deliverableGroup(finalGroup,true)}<div class="twocol"><section class="section"><div class="sectionhead"><h2>项目文件</h2>${btn('项目 AI 总结','project-ai','spark','small')}</div><div id="selection-bar"></div>${array(d.files).length?fileRows(array(d.files),true):empty('项目还没有成果文件','将文件导入本项目，即可统一预览、搜索和管理版本。','import')}${array(d.missing_attachments).length?'<div class="divider"></div><h3>需要补充原文件</h3><p class="footnote">官方导出只包含以下附件的元数据，当前没有可归档的文件实体。请下载原文件后手动导入。</p>'+array(d.missing_attachments).map(m=>`<div class="version"><strong>${esc(m.name || '未命名附件')}</strong><p>${esc(m.status || '需要补充原文件')}</p><small>会话 ${esc(m.conversation_id || '未提供')}</small></div>`).join(''):''}</section><div><section class="section"><h2>任务来源</h2><dl class="kv"><dt>原始 Work 标题</dt><dd>${esc(p.original_title || '用户尚未提供')}</dd><dt>标题来源</dt><dd>${esc(sourceLabel(p.title_source))}</dd><dt>会话标识</dt><dd>${esc(p.conversation_id || '未提供')}</dd><dt>标题获取时间</dt><dd>${time(p.title_obtained_at)}</dd><dt>创建时间</dt><dd>${time(p.created_at)}</dd><dt>最近更新</dt><dd>${time(p.updated_at)}</dd></dl>${array(d.sources).length>1?'<h3>关联的原始任务</h3>'+array(d.sources).map(s=>`<div class="version"><strong>${esc(s.title)}</strong><p>${esc(s.title_source)} · ${esc(s.confidence)}</p><small>${esc(s.conversation_id || '未提供会话 ID')}</small>${s.source_url?`<p><a href="${safeLink(s.source_url)}" target="_blank" rel="noopener noreferrer">打开来源会话 →</a></p>`:''}</div>`).join(''):''}${p.source_url?`<a href="${safeLink(p.source_url)}" target="_blank" rel="noopener noreferrer">${icon('external')} 打开来源会话</a>`:''}<div class="divider"></div><p class="footnote">${p.deepseek_allowed?'本项目已允许向 DeepSeek 发送经预览确认的正文片段。':'默认仅本地处理。DeepSeek 访问权限尚未开启。'}</p>${btn(p.deepseek_allowed?'关闭 DeepSeek 授权':'管理 DeepSeek 授权','project-auth','shield','small')}</section><section class="section"><h2>项目时间线</h2>${activity(array(d.events).slice(0,12))}</section></div></div>`;}
function safeLink(value: unknown): string {try{const u=new URL(String(value));return ['https:','http:'].includes(u.protocol)?attr(u.href):'#';}catch{return '#';}}
function fileSearchExclusionDialog(): void {
 const suffixes=new Set<string>(array(status.file_search_exclusions));
 modal('搜索排除设置',`
  <p>以下后缀会从文件中心的关键词搜索结果中排除。浏览文件时仍会显示这些格式。</p>
  <div class="actions" id="excluded-suffixes" aria-label="已排除的文件后缀"></div>
  <div class="field">
   <label for="new-excluded-suffix">添加后缀</label>
   <div class="actions">
    <input id="new-excluded-suffix" placeholder=".log 或 .log, .tmp" spellcheck="false" autocapitalize="off">
    ${btn('添加','add-excluded-suffix','plus')}
   </div>
   <small>可用空格或逗号分隔多个后缀。点击后缀旁的 × 可移除。</small>
   <small id="excluded-suffix-error" role="alert"></small>
  </div>`,btn('恢复默认','restore-default-exclusions')+btn('取消','close')+btn('保存','save-excluded-suffixes','check','primary'));

 const dialog=$('#modal-root');
 const chips=$('#excluded-suffixes',dialog);
 const input=$<HTMLInputElement>('#new-excluded-suffix',dialog);
 const error=$('#excluded-suffix-error',dialog);
 const save=$<HTMLButtonElement>('[data-action=save-excluded-suffixes]',dialog);
 const showSuffixes=()=>{
  chips.innerHTML=[...suffixes].map(suffix=>
   `<button type="button" class="small" data-remove-exclusion="${attr(suffix)}" aria-label="取消排除 .${attr(suffix)}">.${esc(suffix)} ×</button>`
  ).join('') || '<span class="muted">未排除任何后缀</span>';
 };
 const addSuffixes=()=>{
  const entries=input.value.split(/[\s,，;；、]+/u).filter(Boolean).map(entry=>entry.toLowerCase().replace(/^\./,''));
  if(entries.some(entry=>!/^[a-z0-9][a-z0-9_+-]{0,31}$/.test(entry))){
   error.textContent='请输入文件的最后一段后缀，例如 .log。后缀须以英文字母或数字开头，最多 32 个字符。';
   input.focus();
   return false;
  }
  const next=new Set([...suffixes,...entries]);
  if(next.size>100){
   error.textContent='最多可设置 100 个搜索排除后缀。';
   input.focus();
   return false;
  }
  next.forEach(entry=>suffixes.add(entry));
  input.value='';
  error.textContent='';
  showSuffixes();
  return true;
 };
 chips.onclick=event=>{
  const button=(event.target as HTMLElement).closest<HTMLButtonElement>('[data-remove-exclusion]');
  if(button?.dataset.removeExclusion){
   suffixes.delete(button.dataset.removeExclusion);
   showSuffixes();
   input.focus();
  }
 };
 input.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();addSuffixes();}};
 input.oninput=()=>{error.textContent='';};
 $('[data-action=add-excluded-suffix]',dialog).onclick=()=>{if(addSuffixes())input.focus();};
 $('[data-action=restore-default-exclusions]',dialog).onclick=()=>{
  suffixes.clear();
  array(status.file_search_default_exclusions).forEach(suffix=>suffixes.add(suffix));
  input.value='';
  error.textContent='';
  showSuffixes();
 };
 save.onclick=()=>void run(async()=>{
  if(!addSuffixes())return;
  save.disabled=true;
  try {
   await rpc('settings_save',{values:{file_search_excluded_extensions:[...suffixes]}});
   closeModal();
   offset=0;
   toast('搜索排除设置已保存');
   await render();
  } finally {save.disabled=false;}
 });
 showSuffixes();
}

async function filesPage(): Promise<string> {const pending=page==='inbox',trash=page==='trash',fileCenter=!pending&&!trash;
 const excludedExtensions=fileCenter?array(status.file_search_exclusions):['md','markdown'];
 if(String(filter.q).trim()&&excludedExtensions.includes(String(filter.ext).toLowerCase()))filter.ext='';
 const r=await rpc('files',{...filter,status:pending?'pending':trash?'trash':'managed',search_context:fileCenter?'file_center':null,limit:40,offset});files=array(r.items);total=Number(r.total)||0;return `<div class="pagehead"><div><h1>${pending?'待确认收件箱':trash?'回收站':'文件中心'}</h1><p>${pending?'确认文件来源与项目归属，让档案保持清晰可靠。':trash?'误删文件可以恢复。此处操作仅影响本地 WorkVault 档案。':'预览、检索和管理你的全部 Work 成果。'}</p></div><div class="actions">${!trash?btn('检查外部编辑','check-edits','refresh'):''}${!trash?btn('导入文件','import','upload','primary'):''}</div></div>${pending&&status.pending_projects?`<div class="notice warning">${icon('info')}另有 ${status.pending_projects} 个官方导出会话无法区分 Chat / Work。请在项目中心打开候选项目，确认属于 Work 后纳入正式档案。${btn('查看候选项目','goto-projects','folder','small')}</div>`:''}${pending?'<div class="notice">'+icon('info')+'下载目录中的文件不会被自动认定为 Work 成果。请选择文件，确认属于 Work 后再关联项目。</div>':''}<div class="toolbar"><input id="file-q" placeholder="搜索文件名、项目名或标签…" value="${attr(filter.q)}">${fileCenter?btn('搜索排除','file-search-exclusions','settings','small'):''}<select id="file-project">${projectOptions('全部项目').map(([v,l])=>`<option value="${attr(v)}" ${v===filter.project_id?'selected':''}>${esc(l)}</option>`).join('')}</select><select id="file-ext"><option value="">全部格式</option>${['pdf','docx','xlsx','pptx','md','txt','csv','json','py','png','jpg','webp','zip'].map(x=>`<option value="${x}" ${filter.q&&excludedExtensions.includes(x)?'disabled':''} ${x===filter.ext?'selected':''}>${x.toUpperCase()}</option>`).join('')}</select><select id="file-sort">${[['newest','最近更新'],['oldest','最早更新'],['name','文件名称'],['size','文件大小']].map(([v,l])=>`<option value="${v}" ${filter.sort===v?'selected':''}>${l}</option>`).join('')}</select><button id="favorite-filter" class="${filter.favorite?'primary':''}" title="仅收藏">${icon('star')}</button><div class="segmented"><button data-action="view-list" class="${listMode==='list'?'active':''}" title="列表视图">${icon('list')}</button><button data-action="view-grid" class="${listMode==='grid'?'active':''}" title="网格视图">${icon('grid')}</button></div></div><div id="selection-bar"></div>${array(r.search_excluded_extensions).length?`<p class="footnote" data-search-excluded-extensions>关键词搜索已排除 ${array(r.search_excluded_extensions).map(ext=>'.'+esc(ext)).join('、')}。清除关键词后可正常浏览。</p>`:''}<section class="section">${files.length?(listMode==='grid'?fileGrid(files):fileRows(files,true)):empty(filter.q?'没有找到相关文件':pending?'收件箱已清空':trash?'回收站为空':'文件库等待你的第一份成果',filter.q?'尝试其他关键词或清除筛选条件。':pending?'新发现但来源不明的文件会在这里等待确认。':'拖拽文件或文件夹到此窗口，或使用导入按钮。',!pending&&!trash&&!filter.q?'import':'')}<div class="pager"><span>共 ${total} 份文件${total?` · 第 ${Math.floor(offset/40)+1} / ${Math.ceil(total/40)} 页`:''}</span><div class="actions"><button data-action="prev" ${offset===0?'disabled':''}>上一页</button><button data-action="next" ${offset+40>=total?'disabled':''}>下一页</button></div></div></section>`;}
async function sourcesPage(): Promise<string> {const d=await rpc('sources');return `<div class="pagehead"><div><h1>同步与接收中心</h1><p>只观察你授权的目录，原始文件始终保留。</p></div><div class="actions">${btn('历史数据导入','history','book')}${btn('添加接收目录','add-source','plus')}${array(d.items).some(s=>s.kind==='codex_outputs')?'':btn('接收 Codex 成果','add-codex-source','folder')}${btn('扫描授权目录','scan','sync','primary')}</div></div><div class="notice">${icon('shield')}ChatGPT 个人账户的 Work 任务与文件公开授权接口当前未验证可用。下方状态只表示本地文件接收，不表示已连接 ChatGPT 账号。</div><section class="section"><h2>文件来源</h2><div class="sourcecard"><span class="foldericon">${icon('lock')}</span><div class="sourcebody"><h3>ChatGPT 官方账户接口 <span class="badge gray">当前不可用</span></h3><p>不会读取登录 Cookie、应用私有数据库或浏览器凭据。</p><p>替代方式：保存成果至专用目录、拖拽导入，或通过官方导出包获取任务标题。</p></div></div>${array(d.items).map(s=>`<div class="sourcecard"><span class="foldericon">${icon(s.kind==='downloads'?'download':'inbox')}</span><div class="sourcebody"><h3>${s.kind==='downloads'?'下载目录 · 待确认来源':s.kind==='codex_outputs'?'Codex 成果目录':'Work 专用接收目录'} <span class="badge ${s.enabled?'green':'gray'}">${s.enabled?'监控已启用':'已暂停'}</span></h3><p>${esc(s.path)}</p>${s.kind==='codex_outputs'?'<p>接收各任务 outputs 中的新文件及更新文件，归属可在待确认收件箱核对。</p>':''}<p>最近扫描：${time(s.last_scan)}${s.error?' · '+esc(s.error):''}</p></div><button class="small" data-source-toggle="${attr(s.id)}" data-enabled="${s.enabled?'0':'1'}">${s.enabled?'暂停':'启用'}</button><button class="small danger" data-source-delete="${attr(s.id)}">移除</button></div>`).join('')}${!array(d.items).length?empty('还没有启用目录监控','添加一个明确授权的目录。系统只登记稳定文件，忽略临时下载与符号链接。','add-source','添加目录','folder'):''}</section><div class="twocol"><section class="section"><h2>接收日志</h2><div class="loglist">${activity(array(d.logs))}</div></section><section class="section"><h2>可靠的标题关联</h2><p class="muted" style="font-size:12px">使用官方导出中的会话标题，或主动粘贴 Work 标题和链接。仅凭文件名推测的标题不会被当作原始任务标题。</p>${btn('新建关联项目','new-project','link')}${btn('导入官方导出包','history','book')}</section></div><section class="section"><div class="sectionhead"><h2>导入任务</h2>${btn('刷新任务','import-jobs','refresh','small')}</div><div id="import-jobs">${await importJobsHTML()}</div></section>`;}
async function importJobsHTML(): Promise<string> {try{const d=await rpc('import_jobs');return array(d.items).slice(0,20).map(j=>`<div class="activity"><div class="circle">${icon(j.status==='failed'?'info':'upload')}</div><div style="flex:1"><p>${esc(j.source || j.id)} · ${esc(j.status || '')}</p><small>${time(j.created_at)} ${esc(j.error || '')}</small></div>${['failed','partial','cancelled'].includes(j.status)?`<button class="small" data-retry="${attr(j.id)}">重试</button>`:''}</div>`).join('')||'<p class="muted">暂无导入任务</p>';}catch{return '<p class="muted">暂无可显示的导入记录</p>';}}
async function settingsPage(): Promise<string> {const d=await rpc('settings'),s=d.settings || {};let resources: Obj={};try{resources=await rpc('resources');const startup=await rpc('startup_status');s.startup=startup.enabled;}catch{}return `<div class="pagehead"><div><h1>设置与数据管理</h1><p>你的文件、你的设备、你的控制权。</p></div>${btn('在浏览器中打开','open-browser','external')}</div><div class="settinggrid"><section class="section"><h2>本地文件库</h2><p class="code">${esc(status.root)}</p><dl class="kv"><dt>档案空间</dt><dd>${bytes(status.bytes)}</dd><dt>磁盘剩余</dt><dd>${bytes(status.free_bytes)}</dd><dt>版本</dt><dd>${esc(status.version || '1.0.0')}</dd></dl><div class="actions">${btn('迁移存储位置','migrate','folder')}${btn('选择已有文件库','switch-library','folder')}${btn('检查文件完整性','integrity','shield')}</div><div class="divider"></div><h3>手动备份与恢复</h3><p class="muted" style="font-size:12px">不会自动或定时备份。备份包含数据库与文件版本、SHA-256 清单，密钥不随备份导出。</p><div class="actions">${btn('创建备份','backup','download')}${btn('校验 / 恢复备份','restore','refresh')}</div></section><section class="section"><h2>应用与资源</h2>${selectField('theme','外观主题',[['system','跟随系统'],['light','浅色'],['dark','深色']],String(s.theme || localStorage.getItem('wv-theme') || 'system'))}<label class="checkfield"><input name="startup" type="checkbox" ${s.startup?'checked':''}>登录 Mac 后启动 WorkVault（默认关闭）</label>${field('scan_interval','目录扫描间隔（秒）',s.scan_interval || 15,'number','最低建议 10 秒；仅扫描已授权目录，不解析正文。')}<div class="actions">${btn('保存应用设置','save-settings','check','primary')}${btn('查看资源','resources','disk')}</div><p class="footnote" style="margin-top:14px">${esc(resources.pid?'进程 PID '+resources.pid:'资源数据按需读取')} ${resources.memory_bytes?' · 内存 '+bytes(resources.memory_bytes):''}</p><div class="divider"></div>${btn('查看本地日志','logs','list')}${btn('退出并停止服务','shutdown','power','danger')}</section></div><section class="section"><div class="sectionhead"><h2>可选 AI 配置</h2><span class="badge gray">默认关闭 · 手动触发</span></div><div class="notice">${icon('shield')}导入、扫描与启动应用都不会分析文件正文或调用模型。DeepSeek 会将预览确认的必要片段发送到其服务。</div><div id="ai-settings"><div class="formgrid">${field('ollama_url','本地 Ollama 地址',s.ollama_url || 'http://127.0.0.1:11434','url','仅允许本机回环地址；不自动启动或下载模型。')}${field('ollama_model','本地推理模型',s.ollama_model || '','','请填写已经下载的本地模型名称。')}${field('embedding_model','本地嵌入模型',s.embedding_model || '','','建立语义索引时使用；不会发送到 DeepSeek。')}${field('deepseek_url','DeepSeek 官方 API 地址',s.deepseek_url || 'https://api.deepseek.com','url')}${field('deepseek_model','DeepSeek 模型名称',s.deepseek_model || 'deepseek-flash','','可随官方模型更新修改。')}${field('ai_timeout','请求超时（秒）',s.ai_timeout || 120,'number')}${field('ai_max_chars','单次最多正文字符',s.ai_max_chars || 12000,'number')}${field('ai_max_tokens','最大输出 Token',s.ai_max_tokens || 1200,'number')}${field('price_input','输入价格（每百万 Token）',s.price_input ?? '','number','按你核实的官方当前价格填写，币种需保持一致。')}${field('price_output','输出价格（每百万 Token）',s.price_output ?? '','number')}${field('budget_request','单次费用上限',s.budget_request ?? '','number')}${field('budget_day','每日费用上限',s.budget_day ?? '','number')}${field('budget_month','每月费用上限',s.budget_month ?? '','number')}</div><div class="actions">${btn('保存 AI 配置','save-ai-settings','check','primary')}${btn('配置 API Key','api-key','lock')}${btn('检测本地 AI','ai-detect','refresh')}</div><p class="footnote" style="margin-top:15px">API Key 存入 macOS Keychain。价格或预算未配置时，收费请求会被阻止。不会要求 ChatGPT 密码。</p></div></section><section class="section"><h2>关于 WorkVault</h2><p class="muted" style="font-size:12px">为本地成果管理而构建 · Apple Silicon 原生入口 · 本地 SQLite 与文件存储 · 无遥测<br>当前交付为本机未公证构建。官方接口状态及限制请查看随附文档。</p><div class="actions">${btn('管理主题分类','categories','tag')}${btn('重新查看引导','onboarding','info')}</div></section>`;}
async function aiPage(): Promise<string> {let a: Obj={};try{a=await rpc('ai_status');}catch(e){a={error:e instanceof Error?e.message:String(e)};}return `<div class="pagehead"><div><h1>AI 知识中心</h1><p>由你主动开启分析，让知识保留来源。</p></div><div class="actions">${activeJob?btn('查看运行中任务','job-resume','clock'):''}${btn('AI 配置','goto-settings','settings')}</div></div><div class="AIhero">${icon('spark')}<div><h2>需要时，再让 AI 参与。</h2><p>普通文件管理无需模型。正文提取、全文索引、嵌入和云端推理均由你手动触发。</p></div></div><div class="stats">${stat('本地 Ollama',a.ollama_available?'可连接':'未连接',array(a.models).length+' 个可用模型','spark')}${stat('DeepSeek',a.key_access_deferred?'钥匙串状态待授权':a.key_configured?'已配置密钥':'未配置','仍需逐项目授权与发送确认','lock')}${stat('已索引片段',a.indexed_chunks || 0,'本地持久化检索索引','book')}${stat('API 请求次数',array(a.requests).length,'按实际请求记录统计','sync')}</div>${a.error?`<div class="notice warning">${esc(a.error)}</div>`:''}${a.key_access_deferred?`<div class="notice">${icon('lock')}${esc(a.note || '钥匙串状态暂不可访问；不会在查看状态时请求密钥权限。')}</div>`:''}<div class="twocol"><section class="section"><h2>检索本地知识</h2><div class="toolbar"><input id="ai-query" placeholder="输入研究问题或检索关键词…"><button data-action="ai-search" class="primary">${icon('search')} 检索</button></div><div class="actions"><select id="ai-project">${projectOptions('全部已索引项目').map(([v,l])=>`<option value="${attr(v)}">${esc(l)}</option>`).join('')}</select><label class="checkfield"><input id="semantic" type="checkbox">使用本地语义检索</label></div><div id="ai-results">${empty('每个答案，都从真实文件开始','先为文件或项目手动建立索引，再检索相关片段。不支持的内容会显示真实解析状态。','','','book')}</div></section><section class="section"><h2>手动分析与索引</h2><p class="muted" style="font-size:12px">为单个文件、多个文件或整个项目执行摘要、标签建议、主题分析、比较或跨文件问答。</p><div class="actions">${btn('开始 AI 分析','ai-compose','spark','primary')}${btn('建立 / 重建索引','ai-index','book')}${btn('删除索引','ai-delete-index','trash')}${btn('检测本地服务','ai-detect','refresh')}</div><div class="divider"></div><h3>项目云端权限</h3><p class="footnote">默认只允许本地处理。允许 DeepSeek 后，每次发送仍需预览确认；关闭权限不会删除服务此前已接收的数据。</p>${btn('管理项目授权','manage-auth','shield')}</section></div><section class="section"><h2>实际 API 使用记录</h2><div class="tablewrap"><table><thead><tr><th>时间</th><th>服务 / 模型</th><th>状态</th><th>输入 Token</th><th>输出 Token</th><th>估算费用</th></tr></thead><tbody>${array(a.requests).slice(0,30).map(r=>`<tr><td>${time(r.created_at)}</td><td>${esc(r.provider || '')} / ${esc(r.model || '')}</td><td>${esc(r.status || '')}</td><td>${esc(r.input_tokens ?? '—')}</td><td>${esc(r.output_tokens ?? '—')}</td><td>${esc(r.estimated_cost ?? r.cost ?? '—')}</td></tr>`).join('')}</tbody></table></div>${!array(a.requests).length?'<p class="chartempty">没有发生 AI 请求；导入文件不会自动调用 AI。</p>':''}</section>`;}
function bindPage(): void {bindActions($('#content'));bindDeliverables($('#content'));if(page==='deliverables')bindDeliverableFilters();$$('[data-page]',$('#content')).forEach(n=>n.onclick=e=>{e.preventDefault();void go(n.dataset.page!);});$$('[data-project]').forEach(n=>n.onclick=e=>{e.preventDefault();projectID=n.dataset.project!;page='project';selected.clear();void render();});bindFiles($('#content'));if(page==='projects'){const update=()=>{const q=$<HTMLInputElement>('#project-search').value.toLowerCase(),c=$<HTMLSelectElement>('#project-category').value,s=$<HTMLSelectElement>('#project-status').value;$('#project-list').innerHTML=projectCards(projects.filter(p=>(!q||[p.title,p.category,p.description].join(' ').toLowerCase().includes(q))&&(!c||p.category===c)&&(!s||p.status===s)));$$('[data-project]',$('#project-list')).forEach(n=>n.onclick=()=>{projectID=n.dataset.project!;page='project';void render();});};['#project-search','#project-category','#project-status'].forEach(s=>$(s).addEventListener(s==='#project-search'?'input':'change',update));}if(['files','inbox','trash'].includes(page)){let timer: ReturnType<typeof setTimeout>;$('#file-q').addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{filter.q=$<HTMLInputElement>('#file-q').value.trim();offset=0;void render();},450);});['project','ext','sort'].forEach(k=>$(`#file-${k}`).onchange=()=>{filter[k==='project'?'project_id':k]=$<HTMLSelectElement>(`#file-${k}`).value;offset=0;void render();});$('#favorite-filter').onclick=()=>{filter.favorite=!filter.favorite;offset=0;void render();};}$$('[data-source-toggle]').forEach(n=>n.onclick=()=>void run(async()=>{const d=await rpc('sources'),s=array(d.items).find(x=>x.id===n.dataset.sourceToggle);await rpc('source_save',{...s,enabled:n.dataset.enabled==='1'});await render();}));$$('[data-source-delete]').forEach(n=>n.onclick=()=>void run(async()=>{await rpc('source_delete',{id:n.dataset.sourceDelete});await render();}));$$('[data-retry]').forEach(n=>n.onclick=()=>void run(async()=>{await rpc('import_retry',{id:n.dataset.retry});toast('重试已完成');await render();}));}
function bindActions(root: ParentNode): void {$$('[data-action]',root).forEach(n=>n.onclick=e=>{e.preventDefault();void run(()=>action(n.dataset.action!,n));});}
async function run(fn: ()=>Promise<unknown>|unknown): Promise<void> {try{await fn();}catch(e){fail(e);}}
function bindFiles(root: ParentNode): void {$$('[data-detail]',root).forEach(n=>n.onclick=e=>{if((e.target as HTMLElement).closest('[data-select]'))return;e.preventDefault();void run(()=>fileDetail(n.dataset.detail!));});$$('[data-open]',root).forEach(n=>n.onclick=e=>{e.preventDefault();e.stopPropagation();void run(async()=>{await rpc('open_file',{id:n.dataset.open});toast('已打开受管理工作副本。编辑完成后点击“检查外部编辑”。');});});$$<HTMLInputElement>('[data-select]',root).forEach(n=>n.onclick=e=>{e.stopPropagation();n.checked?selected.add(n.dataset.select!):selected.delete(n.dataset.select!);n.closest('tr,.filecard')?.classList.toggle('selected',n.checked);selectionBar();});const all=$<HTMLInputElement>('#select-all',root);if(all)all.onchange=()=>{$$<HTMLInputElement>('[data-select]',root).forEach(n=>{n.checked=all.checked;n.checked?selected.add(n.dataset.select!):selected.delete(n.dataset.select!);n.closest('tr,.filecard')?.classList.toggle('selected',n.checked);});selectionBar();};$$('[data-context]',root).forEach(n=>n.onclick=e=>{e.preventDefault();e.stopPropagation();showContext(n.dataset.context!,e as MouseEvent);});$$('[data-file]',root).forEach(n=>n.oncontextmenu=e=>{e.preventDefault();showContext(n.dataset.file!,e);});selectionBar();}
function selectionBar(): void {const n=$('#selection-bar');if(!n)return;n.innerHTML=selected.size?`<div class="selectedbar"><span>已选择 ${selected.size} 份文件</span>${page==='trash'?btn('恢复','batch-restore','refresh','small'):btn(page==='inbox'?'确认归属':'关联项目','batch-project','folder','small')+btn('标签','batch-tags','tag','small')+btn('收藏','batch-favorite','star','small')+btn(page==='inbox'?'忽略 / 移出':'移至回收站','batch-trash','trash','small danger')}${btn('取消选择','deselect','','small')}</div>`:'';bindActions(n);}
function showContext(id: string,e: MouseEvent): void {contextNode?.remove();contextNode=document.createElement('div');contextNode.className='context';contextNode.style.left=Math.min(e.clientX,window.innerWidth-200)+'px';contextNode.style.top=Math.min(e.clientY,window.innerHeight-260)+'px';contextNode.innerHTML=btn('预览与详情','ctx-detail','files')+btn('使用默认应用打开','ctx-open','external')+btn('Finder 中定位','ctx-reveal','folder')+btn('重命名','ctx-rename','edit')+btn('导出文件','ctx-export','download')+btn('移至回收站','ctx-trash','trash','danger');document.body.append(contextNode);$$('[data-action]',contextNode).forEach(n=>n.onclick=()=>{contextNode?.remove();void run(async()=>{switch(n.dataset.action){case'ctx-detail':await fileDetail(id);break;case'ctx-open':await rpc('open_file',{id});toast('已打开可编辑工作副本');break;case'ctx-reveal':await rpc('reveal_file',{id});break;case'ctx-rename':await renameFile(id);break;case'ctx-export':await exportFile(id);break;case'ctx-trash':await rpc('file_update',{ids:[id],status:'trash'});toast('已移至回收站');await render();break;}});});}
async function action(a: string,_node?: HTMLElement): Promise<void> {if(a.startsWith('goto-')){await go(a.slice(5));return;}switch(a){case'close':closeModal();break;case'reload':await render();break;case'file-search-exclusions':fileSearchExclusionDialog();break;case'final-pick':await finalPicker(page==='project'?projectID:String(finalFilter.project_id || ''));break;case'final-all':finalFilter={q:'',project_id:'',offset:0};await render();break;case'final-prev':finalFilter.offset=Math.max(0,Number(finalFilter.offset)-(finalFilter.project_id?40:12));await render();break;case'final-next':finalFilter.offset=Number(finalFilter.offset)+(finalFilter.project_id?40:12);await render();break;case'theme':{const current=document.documentElement.dataset.theme;setTheme(current==='dark'?'light':'dark');await rpc('settings_save',{values:{theme:localStorage.getItem('wv-theme')}});break;}case'new-project':await projectForm();break;case'confirm-project':await rpc('project_confirm',{id:projectID});toast('已由用户确认属于 Work');await render();break;case'edit-project':await projectForm((await rpc('project_detail',{id:projectID})).project);break;case'import':await importDialog();break;case'history':await historyImport();break;case'backup':await backup();break;case'restore':await restore();break;case'migrate':await migrate();break;case'switch-library':{const path=await pickDirectory();if(path&&await confirmDialog('切换已有文件库',`将当前文件库切换至：${path}。两个目录的数据都会保留。`,'切换文件库')){await rpc('switch_library',{path});toast('文件库已切换');await render();}break;}case'integrity':{toast('正在校验文件，请稍候…');const r=await rpc('integrity');modal('文件完整性检查',`<p>已检查 ${esc(r.checked)} 个文件实体。</p><div class="result">${esc(array(r.errors).length?array(r.errors).join('\n'):'所有已检查文件的 SHA-256 校验通过。')}</div>`);break;}case'logs':{const r=await rpc('logs');modal('本地操作日志',`<div class="loglist">${activity(array(r.items))}</div>`,'',true);break;}case'resources':{const r=await rpc('resources');modal('实时资源状态',`<div class="result">${esc(JSON.stringify(r,null,2))}</div>`);break;}case'open-browser':await rpc('open_browser');break;case'shutdown':if(await confirmDialog('退出 WorkVault','退出后，本地服务和目录监控将停止。已保存的文件不会受到影响。','退出并停止')){await rpc('shutdown');$('#app').innerHTML=empty('WorkVault 已停止','关闭此窗口即可。再次双击应用图标可以启动。','','','power');}break;case'project-view-list':case'project-view-grid':projectListMode=a==='project-view-list'?'list':'grid';localStorage.setItem('wv-project-list',projectListMode);await render();break;case'view-list':case'view-grid':listMode=a==='view-list'?'list':'grid';localStorage.setItem('wv-list',listMode);await render();break;case'prev':offset=Math.max(0,offset-40);await render();break;case'next':offset+=40;await render();break;case'deselect':selected.clear();$$<HTMLInputElement>('[data-select]').forEach(n=>n.checked=false);$$('.selected').forEach(n=>n.classList.remove('selected'));selectionBar();break;case'batch-project':await associate([...selected]);break;case'batch-tags':await tagsDialog([...selected]);break;case'batch-favorite':await rpc('file_update',{ids:[...selected],favorite:true});toast('已收藏所选文件');await render();break;case'batch-trash':if(await confirmDialog('移至本地回收站',`将 ${selected.size} 份文件移至 WorkVault 回收站。原始下载和 ChatGPT 会话不受影响。`)){await rpc('file_update',{ids:[...selected],status:'trash'});await render();toast('已移至回收站，可随时恢复');}break;case'batch-restore':await rpc('file_update',{ids:[...selected],status:'managed'});toast('已恢复文件');await render();break;case'add-source':sourceForm();break;case'add-codex-source':sourceForm('codex_outputs');break;case'scan':{const r=await rpc('scan');toast(`扫描完成：发现 ${r.discovered || 0} 份稳定文件${array(r.errors).length?'；部分路径不可访问':''}。新文件需要连续扫描确认写入已完成。`);await render();break;}case'import-jobs':$('#import-jobs').innerHTML=await importJobsHTML();bindPage();break;case'categories':await categoryManager();break;case'delete-project':if(await confirmDialog('删除空项目','仅删除此空项目记录，原始 ChatGPT 会话不会改变。','删除项目')){await rpc('project_delete',{id:projectID});await go('projects');toast('空项目已删除');}break;case'merge-project':await mergeProject();break;case'split-project':await splitProject();break;case'save-settings':{const v=formValues($('#content'));const theme=v.theme;await rpc('settings_save',{values:{theme,scan_interval:Math.max(10,Number(v.scan_interval)||15)}});await rpc('startup_set',{enabled:v.startup});setTheme(theme);toast('应用设置已保存');break;}case'save-ai-settings':{const v=formValues($('#ai-settings'));for(const k of ['ai_timeout','ai_max_chars','ai_max_tokens','price_input','price_output','budget_request','budget_day','budget_month'])if(v[k]!=='')v[k]=Number(v[k]);await rpc('settings_save',{values:v});toast('AI 配置已保存');break;}case'api-key':modal('设置 DeepSeek API Key',`<p class="muted">密钥仅写入 macOS Keychain，不会显示在配置、日志或普通备份中。</p>${field('key','API Key','','password','留空并保存将清除已配置密钥。')}`,btn('取消','close')+btn('保存到 Keychain','save-key','lock','primary'));break;case'save-key':await rpc('ai_key',{key:formValues().key});closeModal();toast('Keychain 凭据已更新');break;case'ai-detect':{toast('正在检测本地服务…');const d=await rpc('ai_status');modal('AI 服务检测',`<dl class="kv"><dt>Ollama</dt><dd>${d.ollama_available?'服务可连接':'未检测到本地服务'}</dd><dt>模型</dt><dd>${esc(array(d.models).join('、') || '未发现可用模型')}</dd><dt>DeepSeek 密钥</dt><dd>${d.key_access_deferred?'钥匙串状态暂不可访问（尚未读取密钥）':d.key_configured?'已配置':'未配置'}</dd></dl><p class="footnote">检测不会下载模型、启动推理或发起收费调用。Ollama 需由你单独安装并启动。</p>`);break;}case'project-auth':await authDialog(projectID);break;case'manage-auth':await authDialog();break;case'job-resume':if(activeJob)await showJob(activeJob,'AI 任务');break;case'ai-compose':await aiCompose();break;case'project-ai':await aiCompose(projectID,'project_summary');break;case'ai-index':await indexDialog(false);break;case'ai-delete-index':await indexDialog(true);break;case'ai-search':await aiSearch();break;case'check-edits':await checkEdits();break;case'onboarding':onboardStep=0;setupData={root:status.root};renderOnboarding();break;}}
async function pickDirectory(): Promise<string|null> {const d=await rpc('choose_directory');return d.path || null;}
